194	// isMemoShareExpired returns true if the share has a defined expiry that has already passed.
195	func isMemoShareExpired(ms *store.MemoShare) bool {
196		return ms.ExpiresTs != nil && time.Now().Unix() > *ms.ExpiresTs
197	}
